48	2111	\N	2024-05-30 15:06:09.138	66.50	[{"id": 2, "kind": "2111", "path": "/mnt/core-data/appfiles/pgpg/uploadedFiles/1/51/SESSION_2111_2.mp4", "size": "70067.8 kb", "shown": true, "status": "SOUMETTRE", "sujetPV": null, "dateDepot": "30-05-2024 15:06:09", "dateUpload": "30-05-2024 15:05:11", "pvDocument": null, "responsable": null, "originalName": "Capsule ReactJS(Composants).mp4", "dateTelechargement": null}]	DONE	\N	SOUMETTRE	\N	\N
